import _ "embed"

// Icon512 is the logo as a 512×512 PNG.
//
//go:embed icon-512.png
var Icon512 []byte

// Icon256 is the logo as a 256×256 PNG.
//
//go:embed icon-256.png
var Icon256 []byte

// IconSVG is the logo as SVG.
//
//go:embed icon.svg
var IconSVG []byte
